from __future__ import absolute_import
from taf.selenium.gnb.oam.coam.cu import pages


class CertificateManagement(pages.CertificateManagement):

    def __init__(self, driver, version):
        if not self._instance_dict:
            super(CertificateManagement, self).__init__(driver, version)
            self._instance_dict.update(
                {"Operator Certificates":
                    OperatorCertificatesPageV25R1(driver, version),
                 "Certificate Revocation List":
                     CertificateRevocationListPageV25R1(driver, version),
                 "Automatic Management":
                     AutomaticManagementPageV25R1(driver, version)})


class OperatorCertificatesPageV25R1(pages.OperatorCertificatesPage):
    MENU_ROUTE_LIST = ['security', 'Certificate Management',
                       'Operator Certificates']


class CertificateRevocationListPageV25R1(pages.CertificateRevocationListPage):
    MENU_ROUTE_LIST = ['security', 'Certificate Management',
                       'Certificate Revocation List']


class AutomaticManagementPageV25R1(pages.AutomaticManagementPage):
    MENU_ROUTE_LIST = ['security', 'Certificate Management',
                       'Automatic Management']
